// ─── v207 storyteller previews — baked in, not fetched ─────────────────────
// The Personal Study card's preview ("Last time in… / This time in… /
// cliffhanger question") was generated live by server/routers/bible.ts
// before v205; v205 severed the display and the old fetch kept running
// unwatched. His call (2026-10-23): ship the previews as local data,
// written ahead of time — offline, instant, nothing to break. The
// server route stays in the tree; the card no longer depends on it.
// PREVIEWS (previews.ts, generated by scripts/gen-previews.mjs) holds
// one entry per chapter: `recap` is the previous chapter's key event,
// `preview` this chapter's main action, `question` the cliffhanger —
// the storyteller's own three beats. The labels are composed here:
// for chapter N > 1 the "last time" is the same book's chapter N−1;
// for chapter 1 it is the previous book's final chapter (canon
// order); Genesis 1 has no last time at all. A chapter with no baked
// entry composes to null, and the card shows its position lines only —
// no error text, no spinner.

import { CHAPTER_COUNTS } from './index';
import { PREVIEWS, type ChapterPreview } from './previews';

export type { ChapterPreview };

/** Canon order — CHAPTER_COUNTS is declared in canon order. */
export const CANON_BOOKS: string[] = Object.keys(CHAPTER_COUNTS);

export interface ComposedPreview {
  /** "Last time in Leviticus 18:" — null only where there is no last
   * chapter (Genesis 1). */
  lastLabel: string | null;
  lastText: string | null;
  /** "This time in Leviticus 19:" */
  thisLabel: string;
  thisText: string;
  question: string;
}

export function composePreview(
  book: string,
  chapter: number,
  data: Record<string, Record<number, ChapterPreview>> = PREVIEWS,
  counts: Record<string, number> = CHAPTER_COUNTS,
): ComposedPreview | null {
  const entry = data[book]?.[chapter];
  if (!entry) return null;
  let lastLabel: string | null = null;
  if (chapter > 1) {
    lastLabel = `Last time in ${book} ${chapter - 1}:`;
  } else {
    const idx = CANON_BOOKS.indexOf(book);
    if (idx > 0) {
      const prevBook = CANON_BOOKS[idx - 1];
      const prevCount = counts[prevBook];
      if (prevBook && prevCount) lastLabel = `Last time in ${prevBook} ${prevCount}:`;
    }
  }
  return {
    lastLabel,
    lastText: lastLabel ? entry.recap : null,
    thisLabel: `This time in ${book} ${chapter}:`,
    thisText: entry.preview,
    question: entry.question,
  };
}

/** The baked preview for the chapter the card points at, or null. */
export function previewFor(book: string, chapter: number): ComposedPreview | null {
  return composePreview(book, chapter);
}
